def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    total = v1 + v2

    return {
        "value": round(total, 3),
        "trace": {
            "v1": v1,
            "v2": v2,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
